import java.util.*;

public class OrmInternalRegistryDemo {

    // 1. EnumMap for mapping entity lifecycle states to handler strategies
    public enum EntityState { MANAGED, DETACHED, TRANSIENT, REMOVED }

    private final Map<EntityState, String> stateHandlers = new EnumMap<>(EntityState.class);

    // 2. IdentityHashMap for tracking cyclic references during hydration
    private final Map<Object, Long> persistenceContextIdentityMap = new IdentityHashMap<>();

    // 3. WeakHashMap for caching transient metadata without preventing GC
    private final Map<Class<?>, MetadataDescriptor> metadataCache = new WeakHashMap<>();

    public void initializeRegistry() {
        stateHandlers.put(EntityState.MANAGED, "DirtyCheckingInterceptor");
        stateHandlers.put(EntityState.DETACHED, "MergeEventListener");
    }

    public void trackHydration(Object entityInstance, Long identifier) {
        persistenceContextIdentityMap.put(entityInstance, identifier);
    }

    public MetadataDescriptor getMetadata(Class<?> entityClass) {
        return metadataCache.computeIfAbsent(entityClass, MetadataDescriptor::new);
    }

    private static class MetadataDescriptor {
        public MetadataDescriptor(Class<?> clazz) { }
    }
}
